// Builds the Claude request from this plug-in's own Settings.
const s = $json;
const business = JSON.stringify({ name: s.name, category: s.category, address: s.address,
  phone: s.phone, website: s.website || null, email: s.email || null }, null, 2);
return { json: { claude_body: {
  model: s.claude_model, max_tokens: 4000,
  tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: 5 },
          { type: 'web_fetch_20250910', name: 'web_fetch', max_uses: 3 }],
  messages: [{ role: 'user', content: s.enrich_prompt.split('{business}').join(business).split('{sources}').join(s.enrichment_sources) }] } } };

const claudeJson = (r) => {
  if (r.error) throw new Error(r.error.message || JSON.stringify(r.error));
  const text = (r.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
  const m = [...text.matchAll(/<json>([\s\S]*?)<\/json>/g)].pop();
  return JSON.parse(m ? m[1] : text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
};
// Plug-in output: the lead exactly as it came in, plus `enrichment` (found data) or `error`.
const leads = $('Lead in').all().map(i => i.json);
return $input.all().map((item, i) => {
  try { return { json: { ...leads[i], enrichment: claudeJson(item.json) } }; }
  catch (e) { return { json: { ...leads[i], error: e.message } }; }
});
